import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import { execFile } from "node:child_process";
import { basename } from "node:path";

const ASK_USER_QUESTION_TOOL = "ask_user_question";

export default function notifications(pi: ExtensionAPI) {
	pi.on("tool_execution_start", (event, ctx) => {
		if (event.toolName === ASK_USER_QUESTION_TOOL) {
			notify(ctx, "Pi needs your input");
		}
	});

	pi.on("agent_settled", (_event, ctx) => {
		notify(ctx, "Pi finished");
	});
}

function notify(ctx: ExtensionContext, title: string) {
	if (process.platform !== "darwin" || ctx.mode !== "tui") return;

	const body = basename(ctx.cwd) || ctx.cwd;
	const script = `display notification ${appleScriptString(body)} with title ${appleScriptString(title)}`;
	execFile("/usr/bin/osascript", ["-e", script], () => {});
}

function appleScriptString(value: string): string {
	return `"${value.replaceAll("\\", "\\\\").replaceAll('"', '\\"')}"`;
}

# Dynamic Island for Mac — SuperIsland

API Reference

## DynamicIsland.island

Control and read the island's activation state.

Controls whether the island is currently showing content, and reads its current display state.

### [`island.activate(autoDismiss?)`](#islandactivateautodismiss)

Activates the island (makes it visible and expanded).

```
// Activate and stay visible
DynamicIsland.island.activate();

// Activate and auto-dismiss after 3 seconds
DynamicIsland.island.activate(3.0);
```

Parameter

Type

Description

`autoDismiss`

`number` (optional)

Seconds before automatic dismissal. Omit to stay visible indefinitely.

### [`island.dismiss()`](#islanddismiss)

Dismisses the island (returns to compact or hides).

```
DynamicIsland.island.dismiss();
```

### [`island.state`](#islandstate)

Read-only. The current display state.

```
console.log(DynamicIsland.island.state);
// "compact" | "expanded" | "fullExpanded"
```

### [`island.isActive`](#islandisactive)

Read-only. Whether the island is currently showing content for this extension.

```
if (!DynamicIsland.island.isActive) {
  DynamicIsland.island.activate(5.0);
}
```

```
function showAlert(message) {
  DynamicIsland.store.set("alertMessage", message);
  DynamicIsland.island.activate(4.0);
  DynamicIsland.playFeedback("warning");
}

DynamicIsland.registerModule({
  expanded() {
    const msg = DynamicIsland.store.get("alertMessage") ?? "Alert";
    return View.hstack([
      View.icon("exclamationmark.triangle.fill", { color: "#f59e0b" }),
      View.text(msg, { style: "subheadline" }),
    ], { spacing: 8 });
  },
});
```

# Dynamic Island for Mac — SuperIsland

API Reference

## DynamicIsland.http

Network fetch API for extensions. Requires the "network" permission.

HTTP client for extensions. Requires `"network"` in your manifest's `permissions` array.

Returns a `Promise` that resolves with the response.

```
const res = await DynamicIsland.http.fetch("https://api.example.com/data");
```

### [Parameters](#parameters)

Parameter

Type

Description

`url`

`string`

Request URL

`options.method`

`string`

HTTP method. Default: `"GET"`

`options.headers`

`object`

Request headers

`options.body`

`string`

Request body (for POST/PUT)

`options.timeout`

`number`

Timeout in seconds. Default: `10`

### [Response](#response)

```
{
  status: number,    // HTTP status code
  data: unknown,     // Parsed JSON (if Content-Type is application/json)
  text: string,      // Raw response text
  error?: string,    // Error message (network error, timeout, etc.)
}
```

### [GET JSON](#get-json)

```
async function getWeather(city) {
  const res = await DynamicIsland.http.fetch(
    `https://wttr.in/${encodeURIComponent(city)}?format=j1`
  );

  if (res.status !== 200 || res.error) {
    console.error("Weather fetch failed:", res.error);
    return null;
  }

  return res.data.current_condition[0];
}
```

```
async function postData(endpoint, payload) {
  const res = await DynamicIsland.http.fetch(endpoint, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${DynamicIsland.settings.get("apiKey")}`,
    },
    body: JSON.stringify(payload),
    timeout: 5,
  });

  return res.data;
}
```

### [Polling with setInterval](#polling-with-setinterval)

```
let status = "unknown";

async function poll() {
  const res = await DynamicIsland.http.fetch("https://status.example.com/api");
  status = res.data?.status ?? "unknown";
}

poll();
setInterval(poll, 30000);

DynamicIsland.registerModule({
  compact() {
    const color = status === "ok" ? "#22c55e" : "#ef4444";
    return View.hstack([
      View.icon("circle.fill", { size: 8, color }),
      View.text(status, { style: "caption" }),
    ]);
  },
});
```

Be a good citizen. Avoid polling more frequently than your data actually changes. Use `refreshInterval` for display updates, but network calls should happen less often (use `setInterval` to separate concerns).

