const STATUS_URL = "file:///tmp/pi-superisland-status.json";
const MAX_INITIAL_AGE_MS = 30_000;

let current = {
  status: "clear",
  project: "Pi",
  timestamp: 0,
};
let lastTimestamp = 0;
let polling = false;

function validStatus(value) {
  return value === "finished" || value === "waiting" || value === "clear";
}

function applyStatus(next) {
  current = next;

  if (next.status === "waiting") {
    DynamicIsland.island.activate();
  } else if (next.status === "finished") {
    DynamicIsland.island.activate(8.0);
  } else {
    DynamicIsland.island.dismiss();
  }
}

async function poll() {
  if (polling) return;
  polling = true;

  try {
    const response = await DynamicIsland.http.fetch(STATUS_URL, { timeout: 1 });
    if (response.error) return;

    const next = response.data ?? JSON.parse(response.text);
    if (
      !next ||
      !validStatus(next.status) ||
      typeof next.project !== "string" ||
      typeof next.timestamp !== "number" ||
      next.timestamp <= lastTimestamp
    ) {
      return;
    }

    const firstPoll = lastTimestamp === 0;
    lastTimestamp = next.timestamp;
    if (firstPoll && Date.now() - next.timestamp > MAX_INITIAL_AGE_MS) return;

    applyStatus(next);
  } catch (error) {
    console.warn("Unable to read Pi status:", error);
  } finally {
    polling = false;
  }
}

DynamicIsland.registerModule({
  compact() {
    const waiting = current.status === "waiting";
    return View.hstack([
      View.icon(waiting ? "person.crop.circle.badge.exclamationmark" : "checkmark.circle.fill", {
        size: 12,
        color: waiting ? "#f59e0b" : "#22c55e",
      }),
      View.text(waiting ? "Pi needs you" : "Pi finished", {
        style: "caption",
        lineLimit: 1,
      }),
    ], { spacing: 5 });
  },

  expanded() {
    const waiting = current.status === "waiting";
    return View.vstack([
      View.hstack([
        View.icon(waiting ? "person.crop.circle.badge.exclamationmark" : "checkmark.circle.fill", {
          size: 18,
          color: waiting ? "#f59e0b" : "#22c55e",
        }),
        View.text(waiting ? "Pi needs your input" : "Pi finished", {
          style: "headline",
          bold: true,
        }),
      ], { spacing: 8 }),
      View.text(current.project, {
        style: "caption",
        color: "#888888",
        lineLimit: 1,
      }),
    ], { spacing: 5, align: "leading" });
  },

  onActivate() {
    poll();
  },
});

poll();
setInterval(poll, 1000);

