import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import { basename } from "node:path";

const ASK_USER_QUESTION_TOOL = "ask_user_question";
const AGENTS_STATUS_URL = "http://127.0.0.1:7823/event";

type State = "Working" | "Waiting" | "Idle" | "Ended";

export default function notifications(pi: ExtensionAPI) {
	pi.on("agent_start", async (_event, ctx) => {
		await publish(ctx, "Working", "UserPromptSubmit");
	});

	pi.on("tool_execution_start", async (event, ctx) => {
		if (event.toolName === ASK_USER_QUESTION_TOOL) {
			await publish(ctx, "Waiting", "AskUserQuestion");
		}
	});

	pi.on("tool_execution_end", async (event, ctx) => {
		if (event.toolName === ASK_USER_QUESTION_TOOL) {
			await publish(ctx, "Working", "InputReceived");
		}
	});

	pi.on("agent_settled", async (_event, ctx) => {
		await publish(ctx, "Idle", "Stop");
	});

	pi.on("session_shutdown", async (_event, ctx) => {
		await publish(ctx, "Ended", "SessionEnd");
	});
}

async function publish(ctx: ExtensionContext, state: State, event: string) {
	if (process.platform !== "darwin" || ctx.mode !== "tui") return;

	try {
		await fetch(AGENTS_STATUS_URL, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({
				state,
				event,
				agent: "Pi",
				session_id: ctx.sessionManager.getSessionId(),
