import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import { rename, writeFile } from "node:fs/promises";
import { basename } from "node:path";

const ASK_USER_QUESTION_TOOL = "ask_user_question";
const STATUS_FILE = "/tmp/pi-superisland-status.json";

type Status = "finished" | "waiting" | "clear";

export default function notifications(pi: ExtensionAPI) {
	pi.on("tool_execution_start", async (event, ctx) => {
		if (event.toolName === ASK_USER_QUESTION_TOOL) {
			await publish(ctx, "waiting");
		}
	});

	pi.on("tool_execution_end", async (event, ctx) => {
		if (event.toolName === ASK_USER_QUESTION_TOOL) {
			await publish(ctx, "clear");
		}
	});

	pi.on("agent_settled", async (_event, ctx) => {
		await publish(ctx, "finished");
	});

	pi.on("session_shutdown", async (_event, ctx) => {
		await publish(ctx, "clear");
	});
}

async function publish(ctx: ExtensionContext, status: Status) {
	if (process.platform !== "darwin" || ctx.mode !== "tui") return;

	const payload = JSON.stringify({
		version: 1,
		status,
		project: basename(ctx.cwd) || ctx.cwd,
		timestamp: Date.now(),
	});
	const temporaryFile = `${STATUS_FILE}.${process.pid}`;

	try {
		await writeFile(temporaryFile, payload);
		await rename(temporaryFile, STATUS_FILE);
	} catch {
		// The island integration must never interrupt the agent.
	}
}

